    async def async_get_segments(self) -> list[Segment]:
        """Return all room segments across all loaded floor maps.

        Each segment is identified by a `{map_flag}:{room_segment_id}` id so
        that the map it belongs to can be recovered when cleaning it. The map
        name is used as the group to let the user distinguish between floors.
        """
        home_trait = self.coordinator.properties_api.home
        return [
            Segment(
                id=f"{vacuum_map.map_flag}:{room.segment_id}",
                name=room.name,
                group=vacuum_map.name,
            )
            for vacuum_map in (home_trait.home_map_info or {}).values()
            for room in vacuum_map.rooms
        ]

    async def async_clean_segments(
        self, segment_ids: list[str], **kwargs: Any
    ) -> None:
        """Clean the given segments.

        Each segment id is expected in the `{map_flag}:{segment_id}` format. All
        segments must belong to the same map. When that map is not the currently
        active one, we switch to it before issuing the clean command.
        """
        # Parse the segment ids into (map_flag, segment_id) integer pairs.
        parsed: list[tuple[int, int]] = []
        for segment_id in segment_ids:
            try:
                map_flag_str, segment_str = segment_id.split(":")
                parsed.append((int(map_flag_str), int(segment_str)))
            except ValueError as err:
                raise ServiceValidationError(
                    translation_domain=DOMAIN,
                    translation_key="segment_id_parse_error",
                    translation_placeholders={"segment_id": segment_id},
                ) from err

        if not parsed:
            return

        map_flags = {map_flag for map_flag, _ in parsed}
        if len(map_flags) > 1:
            raise ServiceValidationError(
                translation_domain=DOMAIN,
                translation_key="multiple_maps_in_clean",
                translation_placeholders={
                    "map_flags": ", ".join(str(flag) for flag in sorted(map_flags))
                },
            )

        target_map = next(iter(map_flags))
        segments = [segment for _, segment in parsed]

        maps_trait = self.coordinator.properties_api.maps
        if maps_trait.current_map != target_map:
            try:
                await maps_trait.set_current_map(target_map)
            except RoborockException as err:
                raise ServiceValidationError(
                    translation_domain=DOMAIN,
                    translation_key="command_failed",
                    translation_placeholders={"command": "load_multi_map"},
                ) from err

        await self.send(RoborockCommand.APP_SEGMENT_CLEAN, {"segments": segments})


